func expected_warning(fork, t: int, held: bool) -> float:
	## The brief's formula (§2), computed here from the cycle numbers, not by calling the fork.
	if held:
		return 0.0
	var p := posmod(t, fork.period)
	if p >= fork.safe_ticks and p < fork.safe_ticks + fork.shadow_ticks:
		return float(p - fork.safe_ticks + 1) / float(fork.shadow_ticks)
	return 0.0

